const {THREE,RAPIER,world,sim,root}=game;
const near=game.entities.find(e=>e.id==='near-bank'&&!e.removed),far=game.entities.find(e=>e.id==='far-bank'&&!e.removed);
const sections=[];let extended=false,length=0,time=0,disposed=false;
const wood=new THREE.MeshStandardMaterial({color:'#38733a',roughness:.95}),leafMat=new THREE.MeshStandardMaterial({color:'#81bb45',roughness:.8});
const cylinder=new THREE.CylinderGeometry(.5,.5,1,10),leafGeo=new THREE.SphereGeometry(.5,10,6);
const start=near?near.position.x+near.half.x-.3:0,end=far?far.position.x-far.half.x+.3:0;
const span=Math.max(0,end-start),count=Math.ceil(span/.23),unit=count?span/count:1;
const top=near?near.position.y+near.half.y:0;
function mesh(geo,mat,parent,x,y,z,sx,sy,sz){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
for(let i=0;i<count;i++){
 const g=new THREE.Group();g.position.set(start+i*unit,top,0);root.add(g);g.visible=false;
 for(let j=0;j<9;j++){const vine=mesh(cylinder,wood,g,unit/2,-.115,-.88+j*.22,.235,unit+.015,.235);vine.rotation.z=Math.PI/2;}
 const leaves=[];
 for(const side of [-1,1]){const l=mesh(leafGeo,leafMat,g,unit*.6,.045,side*1.12,.43,.055,.64);l.rotation.y=side*.6;leaves.push(l);}
 sections.push({g,leaves,c:null,index:i});
}
function update(){for(const s of sections){const amount=THREE.MathUtils.clamp((length-s.index*unit)/unit,0,1);s.g.visible=amount>0;s.g.scale.x=Math.max(.001,amount);
 if(amount>=.999&&!s.c){s.c=world.createCollider(RAPIER.ColliderDesc.cuboid(unit/2,.115,1).setTranslation(start+(s.index+.5)*unit,top-.115,0).setFriction(.9));}
 if(amount<.999&&s.c){world.removeCollider(s.c,true);s.c=null;}
 for(const l of s.leaves){const bloom=THREE.MathUtils.clamp((amount-.35)/.65,0,1);l.scale.set(.43*bloom,.055*bloom,.64*bloom);l.rotation.z=Math.sin(time*2+s.index*.7)*.12;}
}}
return {use(){if(!near||!far){game.say('This vine needs the two banks of the broken bridge.');return;}extended=!extended;game.say(extended?'The vine is growing toward the far bank. Follow the leafy path!':'The vine is retracting from the far bank. Get onto solid ground!');game.sound(extended?240:360,.3,.07,extended?480:130);},step(dt){if(disposed)return;time+=dt;length=THREE.MathUtils.clamp(length+(extended?1:-1)*dt*1.8,0,span);update();},dispose(){disposed=true;for(const s of sections){if(s.c&&s.c.isValid())world.removeCollider(s.c,true);s.g.removeFromParent();}cylinder.dispose();leafGeo.dispose();wood.dispose();leafMat.dispose();}};
